void export(String day, SocketChannel out) throws Exception {
    if (!querySlots.tryAcquire(2, TimeUnit.SECONDS)) {   // 1. wait for a slot, but not forever
        throw new IllegalStateException("statement service busy");
    }
    try {
        renderStatement(day);                              // 2. 1.5 s query, parks the virtual thread
    } finally {
        querySlots.release();                              // 3. free the slot before the slow send
    }
    sendFile(day, out);
}

